import re
import urllib.parse
import requests
import json

def task_func(myString, API_KEY):
    def extract_urls(text):
        if not text:
            return []
        pattern = re.compile(r'(?i)\b((?:https?://|www\.)[^\s<>"\'\]]+)')
        raw_urls = pattern.findall(text)
        cleaned = []
        for url in raw_urls:
            url = url.strip().rstrip('.,;:!?)]}\'"')
            cleaned.append(url)
        return cleaned

    def extract_domain(url):
        parsed = urllib.parse.urlparse(url if re.match(r'(?i)^[a-z][a-z0-9+\-.]*://', url) else 'http://' + url)
        host = parsed.hostname or ""
        return host.lower().rstrip('.')

    def geolocate(domain):
        try:
            query = urllib.parse.quote(domain, safe='')
            endpoint = f"https://ip-api.com/json/{query}"
            params = {"fields": "status,country,region,regionName,city,zip,lat,lon,timezone,isp,org,as,mobile,proxy,query,message"}
            response = requests.get(endpoint, params=params, timeout=10)
            response.raise_for_status()
            data = response.json()
            if isinstance(data, dict) and data.get("status") in {"success", "fail"}:
                return data
        except Exception:
            pass
        return None

    urls = extract_urls(myString)
    domains_in_order = []
    seen = set()

    for url in urls:
        domain = extract_domain(url)
        if domain and domain not in seen:
            seen.add(domain)
            domains_in_order.append(domain)

    result = {}
    for domain in domains_in_order:
        result[domain] = geolocate(domain)

    return result
